#!/usr/bin/env python3
"""Write the real-header case files hdrcases/sample_*.case.

Sources (header cards copied verbatim, minus COMMENT/HISTORY/blank cards
and the time-stamp card DATE, none of which carry WCS information):

  1. Calabretta's Paper II example maps, astropy 8.0.2
     astropy/wcs/tests/data/maps/1904-66_*.hdr (BSD-3-Clause): the
     radio-continuum field 1904-66 reprojected into every Paper II
     projection (27 headers incl. NCP-as-SIN; this is the only real CSC
     header we have - see PROVENANCE.md). All have CRVAL2 = -90 and
     explicit LONPOLE/LATPOLE.
  2. Survey headers with LONPOLE = 0, astropy 8.0.2
     astropy/visualization/wcsaxes/tests/data/{msx_header,rosat_header}
     (BSD-3-Clause): MSX GLON-CAR and ROSAT all-sky GLON-AIT.
  3. HPX / XPH image headers written by /usr/bin/HPXcvt (wcslib 8.10) from
     a 768-pixel NSIDE=8 HEALPix map written by healpy 1.20.1 (see
     make_hpx_samples() below; the maps are regenerated, so this needs the
     venv's healpy and HPXcvt on PATH).

Each case runs a 13 x 13 pixel grid from 12% before to 12% past every image edge
(off-projection pixels of the all-sky maps are part of the golden) plus a
13 x 13 sky grid.

Usage:  <venv>/bin/python gen_sample_cases.py [OUTROOT]   (then: make hdr-goldens)

OUTROOT defaults to this directory; the cases go to OUTROOT/hdrcases and
the HPXcvt image + healpy truth to OUTROOT/samples. TestSampleGeneratorsReproduce
runs it into a temp OUTROOT and requires every committed file back byte
for byte (HPXcvt's DATE and input-path HISTORY cards are pinned, PINNED_CARDS).
"""

import os
import subprocess
import sys
import tempfile

import astropy
from astropy.io import fits

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(sys.argv[1]) if len(sys.argv) > 1 else HERE
OUT = os.path.join(ROOT, "hdrcases")
SAMPLES = os.path.join(ROOT, "samples")
ASTROPY = os.path.dirname(astropy.__file__)

SKIP_KEYS = ("COMMENT", "HISTORY", "DATE    ", "DATE=")

# HPXcvt stamps the file creation time into DATE and the (temp) input path
# into a HISTORY card; both are pinned so re-runs from any checkout write
# the committed image byte for byte. Neither carries WCS or pixel data.
PINNED_CARDS = [
    (b"DATE    ", "DATE    = '2026-11-01T07:52:52' / file creation date (YYYY-MM-DDThh:mm:ss UT)"),
    (b"HISTORY Original input file:", "HISTORY Original input file: ring_gal.fits"),
]


def pin_cards(data):
    """Replace each PINNED_CARDS card in the primary header (matched by its
    prefix) with the pinned text; refuses unless each occurs exactly once."""
    end = data.index(b"END" + b" " * 77)
    for prefix, card in PINNED_CARDS:
        hits = [i for i in range(0, end, 80) if data[i:i + len(prefix)] == prefix]
        if len(hits) != 1:
            raise SystemExit("expected one %r card in the HPXcvt header, found %d" % (prefix, len(hits)))
        i = hits[0]
        data = data[:i] + card.ljust(80).encode("ascii") + data[i + 80:]
    return data


def cards_from_header(hdr):
    out = []
    for card in hdr.cards:
        s = card.image
        if s.startswith(SKIP_KEYS) or not s.strip():
            continue
        out.append(s.rstrip())
    return out


def grid_for(naxis1, naxis2):
    # Non-commensurate grid nodes, 12% past each edge.
    x0, x1 = -0.12 * naxis1 + 0.37, 1.12 * naxis1 + 0.29
    y0, y1 = -0.12 * naxis2 + 0.43, 1.12 * naxis2 + 0.31
    return "GRID %.4f %.4f 13 %.4f %.4f 13" % (x0, x1, y0, y1)


def write_case(name, note, cards, source, extra=()):
    hdr = fits.Header.fromstring("".join(c.ljust(80) for c in cards))
    lines = [
        "# Generated by gen_sample_cases.py from %s" % source,
        "# (header cards verbatim except COMMENT/HISTORY/DATE/blank).",
        "NOTE %s" % note,
        grid_for(hdr["NAXIS1"], hdr["NAXIS2"]),
        "SKYGRID 0.71 359.13 13 -89.37 89.21 13",
    ]
    lines += list(extra)
    lines.append("HEADER")
    lines += cards
    with open(os.path.join(OUT, "sample_%s.case" % name), "w") as f:
        f.write("\n".join(lines) + "\n")


def calabretta():
    d = os.path.join(ASTROPY, "wcs", "tests", "data", "maps")
    n = 0
    for fn in sorted(os.listdir(d)):
        if not fn.startswith("1904-66_") or not fn.endswith(".hdr"):
            continue
        code = fn[len("1904-66_"):-len(".hdr")]
        with open(os.path.join(d, fn), "rb") as f:
            raw = f.read().decode("ascii")
        hdr = fits.Header.fromstring(raw)
        write_case(
            "1904-66_%s" % code.lower(),
            "Calabretta Paper II example map 1904-66_%s (astropy 8.0.2 wcs/tests/data/maps)" % code,
            cards_from_header(hdr),
            "astropy 8.0.2 astropy/wcs/tests/data/maps/%s" % fn,
            extra=[
                "# Sky points near a projection's horizon land at |pixel| up to",
                "# ~3e7 (0.0667 deg/px), where 1e-9 px is below one ULP; 1e-7 px",
                "# absolute (~25 ULP at 3e7 px, 2.4e-5 arcsec) is the budget.",
                "TOL_PX 1e-7",
            ],
        )
        n += 1
    return n


def surveys():
    d = os.path.join(ASTROPY, "visualization", "wcsaxes", "tests", "data")
    for fn, name, note in [
        ("msx_header", "msx_glon_car_lonpole0", "MSX GLON-CAR survey header, LONPOLE = 0"),
        ("rosat_header", "rosat_glon_ait_lonpole0", "ROSAT all-sky GLON-AIT survey header, LONPOLE = 0"),
    ]:
        with open(os.path.join(d, fn)) as f:
            hdr = fits.Header.fromtextfile(f)
        cards = ["NAXIS   = 2"] + cards_from_header(hdr)
        # The wcsaxes test headers carry no NAXISn; give the image size
        # the survey used (MSX 150 x 150, ROSAT 480 x 240) so the grid has
        # a frame.
        size = {"msx_header": (150, 150), "rosat_header": (480, 240)}[fn]
        cards.insert(1, "NAXIS1  = %d" % size[0])
        cards.insert(2, "NAXIS2  = %d" % size[1])
        write_case(name, note, cards, "astropy 8.0.2 astropy/visualization/wcsaxes/tests/data/%s" % fn)


def make_hpx_samples():
    import healpy as hp
    import numpy as np

    with tempfile.TemporaryDirectory(dir=ROOT) as tmp:
        m = np.arange(hp.nside2npix(8), dtype=np.float32)
        ring = os.path.join(tmp, "ring_gal.fits")
        hp.write_map(ring, m, nest=False, coord="G", overwrite=True, dtype=np.float32)
        nest = os.path.join(tmp, "nest_equ.fits")
        hp.write_map(nest, hp.reorder(m, r2n=True), nest=True, coord="C", overwrite=True, dtype=np.float32)
        jobs = [
            ("hpxcvt_hpx_gal", [], ring, "HPXcvt GLON-HPX from a RING NSIDE=8 galactic map"),
            ("hpxcvt_hpx_equ", [], nest, "HPXcvt RA-HPX from a NESTED NSIDE=8 equatorial map"),
            ("hpxcvt_hpx_gal_q1", ["-q1"], ring, "HPXcvt -q1 (recentred 90 deg) GLON-HPX"),
            ("hpxcvt_xph_n_gal", ["-xn"], ring, "HPXcvt -xn north-polar XPH"),
            ("hpxcvt_xph_s_gal", ["-xs"], ring, "HPXcvt -xs south-polar XPH"),
        ]
        for name, opts, src, note in jobs:
            out = os.path.join(tmp, name + ".fits")
            subprocess.run(["HPXcvt"] + opts + [src, out], check=True, capture_output=True)
            hdr = fits.getheader(out)
            n1, n2 = hdr["NAXIS1"], hdr["NAXIS2"]
            extra = []
            if name == "hpxcvt_hpx_gal":
                extra = ["# every pixel centre of the image (TestHPXcvtPixelCentres)",
                         "GRID 1 %d %d 1 %d %d" % (n1, n1, n2, n2)]
            write_case(name, note, cards_from_header(hdr),
                       "/usr/bin/HPXcvt %s (wcslib 8.10) on a healpy 1.20.1 NSIDE=8 map" % " ".join(opts),
                       extra=extra)
            if name == "hpxcvt_hpx_gal":
                # Keep the image itself: TestHPXcvtPixelCentres checks every
                # pixel centre against healpy.pix2ang of the HEALPix index
                # stored in it.
                with open(out, "rb") as f:
                    data = pin_cards(f.read())
                with open(os.path.join(SAMPLES, "hpxcvt_hpx_gal_n8.fits"), "wb") as f:
                    f.write(data)
                write_healpy_centres(out, os.path.join(SAMPLES, "hpxcvt_hpx_gal_n8.healpy.json"))


def write_healpy_centres(path, out):
    """healpy truth for every filled pixel of an HPXcvt image: the image
    stores, at each pixel, the RING index of the HEALPix pixel HPXcvt put
    there (the input map was arange(768)), so healpy.pix2ang of that index
    is where that pixel centre must be on the sky."""
    import json

    import healpy as hp
    import numpy as np

    data = fits.getdata(path)
    rows = []
    ny, nx = data.shape
    for j in range(ny):
        for i in range(nx):
            v = data[j, i]
            if not np.isfinite(v):
                continue
            th, ph = hp.pix2ang(8, int(v), nest=False)
            # 1-based FITS pixel, RING index, lon, lat (deg)
            rows.append([i + 1, j + 1, int(v), float(np.degrees(ph)), float(90.0 - np.degrees(th))])
    with open(out, "w") as f:
        json.dump({"source": "healpy %s pix2ang(nside=8, ring) of the image value at each pixel" % hp.__version__,
                   "nside": 8, "rows": rows}, f, indent=0)
        f.write("\n")


def main():
    os.makedirs(OUT, exist_ok=True)
    os.makedirs(SAMPLES, exist_ok=True)
    n = calabretta()
    surveys()
    make_hpx_samples()
    print("wrote %d Calabretta, 2 survey and 5 HPXcvt sample cases" % n)


if __name__ == "__main__":
    main()
